local function Stop()
	SetUnitValue(COB.INBUILDSTANCE, 0)
	CloseYard()
	deactivatescr()
end

local function RequestState(requested)
	local actual = 0
	if state_changing ~= 0 then
		state_desired = requested
		return
	end
	state_changing = 1
	actual = state_desired
	state_desired = requested
	while state_desired ~= actual do
		if state_desired == 0 then
			Go()
			actual = 0
		end
		if state_desired == 1 then
			Stop()
			actual = 1
		end
	end
	state_changing = 0
end

function script.Create()
	s0 = 1
	InitState()
	StartThread(SmokeUnit, {base})
end

function script.Activate()
	Signal(SIG_ACTIVATE)
	StartThread(RequestState, 0)
end

local function Deactivate()
	Signal(SIG_ACTIVATE)
	SetSignalMask(SIG_ACTIVATE)
	SetSignalMask(0)
	StartThread(RequestState, 1)
end

function script.Deactivate()
	StartThread(Deactivate)
end

function script.StopBuilding()
end

function script.StartBuilding(heading, pitch)
end

function script.QueryNanoPiece()
	local piecenum = -1
	if s0 == 1 then
		piecenum = nano1
	end
	if s0 == 2 then
		piecenum = nano2
	end
	if s0 == 3 then
		piecenum = nano3
	end
	if s0 == 4 then
		piecenum = nano4
	end
	s0 = s0 + 1
	if s0 == 5 then
		s0 = 1
	end
	return piecenum
end

function script.QueryBuildInfo()
	return gangplank
end

function script.SweetSpot()
	return base
end

function script.Killed(recentDamage, maxHealth)
	local severity = recentDamage / maxHealth * 100
	if severity <= 25 then
		Explode(arm1a, SFX.NONE + SFX.NO_HEATCLOUD)
		Blow({arm1b, arm2a, arm2b, arm3a}, SFX.NONE)
		Explode(arm3b, SFX.NONE + SFX.NO_HEATCLOUD)
		Blow({arm4a, arm4b, base, clamp1}, SFX.NONE)
		Explode(clamp1b, SFX.NONE + SFX.NO_HEATCLOUD)
		Blow({clamp2, clamp2b, clamp3, clamp3b}, SFX.NONE)
		Explode(clamp4, SFX.NONE + SFX.NO_HEATCLOUD)
		Blow({clamp4b, clamplight1, clamplight2, clamplight3}, SFX.NONE)
		Explode(clamplight4, SFX.NONE + SFX.NO_HEATCLOUD)
		Blow({crane, cranetop, gangplank, glowybits}, SFX.NONE)
		Explode(lathe1, SFX.NONE + SFX.NO_HEATCLOUD)
		Blow({lathe2, lathe3, lathe4}, SFX.NONE)
		return 1
	end
	if severity <= 50 then
		Explode(arm1a, SFX.FALL + SFX.NO_HEATCLOUD)
		Blow({arm1b, arm2a, arm2b, arm3a}, SFX.FALL)
		Explode(arm3b, SFX.FALL + SFX.NO_HEATCLOUD)
		Blow({arm4a, arm4b}, SFX.FALL)
		Blow({base, clamp1}, SFX.NONE)
		Explode(clamp1b, SFX.FALL + SFX.NO_HEATCLOUD)
		Explode(clamp2, SFX.NONE)
		Explode(clamp2b, SFX.FALL)
		Explode(clamp3, SFX.NONE)
		Explode(clamp3b, SFX.FALL)
		Explode(clamp4, SFX.NONE + SFX.NO_HEATCLOUD)
		Blow({clamp4b, clamplight1, clamplight2, clamplight3}, SFX.FALL)
		Explode(clamplight4, SFX.FALL + SFX.NO_HEATCLOUD)
		Blow({crane, cranetop, gangplank, glowybits}, SFX.NONE)
		Explode(lathe1, SFX.FALL + SFX.NO_HEATCLOUD)
		Blow({lathe2, lathe3, lathe4}, SFX.FALL)
		return 2
	end
	if severity <= 99 then
		Explode(arm1a, SFX.EXPLODE_ON_HIT + SFX.FALL + SFX.SMOKE + SFX.FIRE + SFX.NO_HEATCLOUD)
		Blow({arm1b, arm2a, arm2b, arm3a}, SFX.EXPLODE_ON_HIT + SFX.FALL + SFX.SMOKE + SFX.FIRE)
		Explode(arm3b, SFX.EXPLODE_ON_HIT + SFX.FALL + SFX.SMOKE + SFX.FIRE + SFX.NO_HEATCLOUD)
		Blow({arm4a, arm4b}, SFX.EXPLODE_ON_HIT + SFX.FALL + SFX.SMOKE + SFX.FIRE)
		Blow({base, clamp1}, SFX.NONE)
		Explode(clamp1b, SFX.EXPLODE_ON_HIT + SFX.FALL + SFX.SMOKE + SFX.FIRE + SFX.NO_HEATCLOUD)
		Explode(clamp2, SFX.NONE)
		Explode(clamp2b, SFX.EXPLODE_ON_HIT + SFX.FALL + SFX.SMOKE + SFX.FIRE)
		Explode(clamp3, SFX.NONE)
		Explode(clamp3b, SFX.EXPLODE_ON_HIT + SFX.FALL + SFX.SMOKE + SFX.FIRE)
		Explode(clamp4, SFX.NONE + SFX.NO_HEATCLOUD)
		Blow({clamp4b, clamplight1, clamplight2, clamplight3}, SFX.EXPLODE_ON_HIT + SFX.FALL + SFX.SMOKE + SFX.FIRE)
		Explode(clamplight4, SFX.EXPLODE_ON_HIT + SFX.FALL + SFX.SMOKE + SFX.FIRE + SFX.NO_HEATCLOUD)
		Blow({crane, cranetop, gangplank, glowybits}, SFX.NONE)
		Explode(lathe1, SFX.EXPLODE_ON_HIT + SFX.FALL + SFX.SMOKE + SFX.FIRE + SFX.NO_HEATCLOUD)
		Blow({lathe2, lathe3, lathe4}, SFX.EXPLODE_ON_HIT + SFX.FALL + SFX.SMOKE + SFX.FIRE)
		return 3
	end
	Explode(arm1a, SFX.EXPLODE_ON_HIT + SFX.FALL + SFX.SMOKE + SFX.FIRE + SFX.NO_HEATCLOUD)
	Blow({arm1b, arm2a, arm2b, arm3a}, SFX.EXPLODE_ON_HIT + SFX.FALL + SFX.SMOKE + SFX.FIRE)
	Explode(arm3b, SFX.EXPLODE_ON_HIT + SFX.FALL + SFX.SMOKE + SFX.FIRE + SFX.NO_HEATCLOUD)
	Blow({arm4a, arm4b}, SFX.EXPLODE_ON_HIT + SFX.FALL + SFX.SMOKE + SFX.FIRE)
	Blow({base, clamp1}, SFX.NONE)
	Explode(clamp1b, SFX.EXPLODE_ON_HIT + SFX.FALL + SFX.SMOKE + SFX.FIRE + SFX.NO_HEATCLOUD)
	Explode(clamp2, SFX.NONE)
	Explode(clamp2b, SFX.EXPLODE_ON_HIT + SFX.FALL + SFX.SMOKE + SFX.FIRE)
	Explode(clamp3, SFX.NONE)
	Explode(clamp3b, SFX.EXPLODE_ON_HIT + SFX.FALL + SFX.SMOKE + SFX.FIRE)
	Explode(clamp4, SFX.NONE + SFX.NO_HEATCLOUD)
	Blow({clamp4b, clamplight1, clamplight2, clamplight3}, SFX.EXPLODE_ON_HIT + SFX.FALL + SFX.SMOKE + SFX.FIRE)
	Explode(clamplight4, SFX.EXPLODE_ON_HIT + SFX.FALL + SFX.SMOKE + SFX.FIRE + SFX.NO_HEATCLOUD)
	Blow({crane, cranetop, gangplank, glowybits}, SFX.NONE)
	Explode(lathe1, SFX.EXPLODE_ON_HIT + SFX.FALL + SFX.SMOKE + SFX.FIRE + SFX.NO_HEATCLOUD)
	Blow({lathe2, lathe3, lathe4}, SFX.EXPLODE_ON_HIT + SFX.FALL + SFX.SMOKE + SFX.FIRE)
	return 3
end
